def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in into s_out."""
    # Find the longest common prefix
    prefix_len = 0
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] == s_out[i]:
            prefix_len += 1
        else:
            break

    # Find the longest common suffix
    suffix_len = 0
    for i in range(1, min(len(s_in), len(s_out)) + 1):
        if s_in[-i] == s_out[-i]:
            suffix_len += 1
        else:
            break

    # The edit is the part that's different
    if prefix_len + suffix_len >= len(s_in):
        # One string is a prefix/suffix of the other
        if len(s_in) < len(s_out):
            # Insertion
            old_sub = ""
            new_sub = s_out[prefix_len:]
            pos = prefix_len
        else:
            # Deletion
            old_sub = s_in[prefix_len:-suffix_len] if suffix_len > 0 else s_in[prefix_len:]
            new_sub = ""
            pos = prefix_len
    else:
        # Substitution/insertion/deletion in middle
        old_sub = s_in[prefix_len:-suffix_len] if suffix_len > 0 else s_in[prefix_len:]
        new_sub = s_out[prefix_len:-suffix_len] if suffix_len > 0 else s_out[prefix_len:]
        pos = prefix_len

    # Handle special case where we're replacing the whole string
    if len(s_in) == len(old_sub) and len(s_out) == len(new_sub):
        return (old_sub, new_sub, pos)

    # Special handling for our specific case
    if len(s_in) < len(s_out):
        # We're inserting
        if s_out[:len(s_in)] == s_in:
            old_sub = ""
            new_sub = s_out[len(s_in):]
            pos = len(s_in)
        else:
            # Need to find where insertion occurs
            pos = 0
            while pos < len(s_in) and s_in[pos] == s_out[pos]:
                pos += 1
            old_sub = ""
            new_sub = s_out[pos:pos+len(s_out)-len(s_in)]
            pos = pos
    else:
        # We're deleting or substituting
        pos = 0
        while pos < len(s_in) and s_in[pos] == s_out[pos]:
            pos += 1
        if pos == len(s_in):
            old_sub = ""
            new_sub = ""
            pos = len(s_in)
        else:
            old_sub = s_in[pos:]
            new_sub = s_out[pos:]
            pos = pos

    return (old_sub, new_sub, pos)

# Analyze first change: 'cux' -> 'ckgwf'
old_sub, new_sub, pos = find_minimal_edit('cux', 'ckgwf')
print(f"'cux' -> 'ckgwf': old='{old_sub}', new='{new_sub}', pos={pos}")

# Analyze second change: 'kxfcj' -> 'kfdfcdgf'
old_sub2, new_sub2, pos2 = find_minimal_edit('kxfcj', 'kfdfcdgf')
print(f"'kxfcj' -> 'kfdfcdgf': old='{old_sub2}', new='{new_sub2}', pos={pos2}")

